CREATE OR REPLACE FUNCTION public.impl_status_track_status_change()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    NEW.last_status_change_at := now();
  END IF;
  RETURN NEW;
END;
$$;

