-- ==================================================================
-- KAYNAK: seeds/overrides.sql
-- ==================================================================
-- cy overrides: tier koltuk limitleri (Pro=1, Enterprise=5, XL=15).
-- org_seat_limit()'i XL=15 olacak şekilde yeniden tanımlar (orijinal migration XL=10 idi).
CREATE OR REPLACE FUNCTION public.org_seat_limit(_org_id uuid)
RETURNS integer
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public
AS $$
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.organizations o ON o.owner_id = ur.user_id WHERE o.id = _org_id AND ur.role = 'admin')   THEN 51
    WHEN EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.organizations o ON o.owner_id = ur.user_id WHERE o.id = _org_id AND ur.role = 'xl')      THEN 15
    WHEN EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.organizations o ON o.owner_id = ur.user_id WHERE o.id = _org_id AND ur.role = 'premium') THEN 5
    WHEN EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.organizations o ON o.owner_id = ur.user_id WHERE o.id = _org_id AND ur.role = 'pro')     THEN 1
    ELSE 1
  END;
$$;
GRANT EXECUTE ON FUNCTION public.org_seat_limit(uuid) TO authenticated, service_role;

-- ==================================================================
-- effort_pt: realistische Neuberechnung (person-days je Kontrolle).
-- Kalibrierung 2026-09-10 (Dr. Sait: „Tage etwas reduzieren"):
-- Sub/KANN 0.2, SOLLTE 0.4, MUSS 0.75 (vorher 0.25/0.5/1.0 → ca. −20 %).
-- Idempotent: bei jedem Deploy neu gesetzt.
-- ==================================================================
UPDATE public.controls SET effort_pt = GREATEST(0.2, ROUND(
  CASE
    WHEN meta ? 'parent_id' THEN 0.2
    WHEN muss = 'KANN'      THEN 0.2
    WHEN muss = 'MUSS'      THEN 0.75
    WHEN muss = 'SOLLTE'    THEN 0.4
    ELSE 0.4
  END
, 2)::numeric);
ALTER TABLE public.controls ALTER COLUMN effort_pt SET DEFAULT 0.4;


