UPDATE public.controls SET req_de='Werden die Alarmierungspläne auch Lieferanten, Dienstleistern und Dritten zur Verfügung gestellt, sofern dies im Rahmen der Alarmierung erforderlich oder sinnvoll ist? (SOLL)' WHERE framework='KRITIS' AND id='GES-0044.2';
