UPDATE public.controls SET req_de='Sind im Asset-Management berücksichtigte Medizingeräte, die Gesundheitsdaten verarbeiten, jederzeit eindeutig identifizierbar? (MUSS)' WHERE framework='KRITIS' AND id='GES-0051';
