UPDATE public.controls SET req_de='Wird die angemessene Robustheit der Architektur und Funktionalität von Redundanzen sowie Ersatzverfahren regelmäßig, mindestens jährlich, bewertet? (SOLL)' WHERE framework='KRITIS' AND id='GES-0060';
