UPDATE public.controls SET req_de='Werden IT-Systeme in öffentlich zugänglichen Bereichen des Krankenhauses angemessen durch technische oder organisatorische Maßnahmen vor unbefugtem Zugriff geschützt? (MUSS)' WHERE framework='KRITIS' AND id='GES-0064';
UPDATE public.controls SET req_de='Werden Mitarbeiter nachweislich auf die Geheimhaltung sowie die Einhaltung einschlägiger Gesetze, Vorschriften und Regelungen verpflichtet? (MUSS)' WHERE framework='KRITIS' AND id='GES-0065.1';
