UPDATE public.controls SET req_de='Werden nutzer- und aufgabenorientierte Schulungs- und Sensibilisierungsmaßnahmen in einem übergreifenden Konzept geplant? (SOLL)' WHERE framework='KRITIS' AND id='GES-0075';
