UPDATE public.controls SET req_de='Werden die Wirksamkeit der Sicherheitsmaßnahmen sowie die Einhaltung interner Regelungen und normativer Compliance-Anforderungen regelmäßig durch Audits überprüft? (MUSS)' WHERE framework='KRITIS' AND id='GES-0085.1';
