UPDATE public.controls SET req_de='Wird ein System zur Vorbeugung und Erkennung schädlicher Software auf Grundlage der Planungen in angemessener Zeit eingerichtet? (MUSS)' WHERE framework='KRITIS' AND id='GES-0111.2';
