UPDATE public.controls SET req_de='Handelt es sich bei dem betrachteten KI-System um ein KI-Modell mit allgemeinem Verwendungszweck (GPAI-Modell), und ist dies dokumentiert klassifiziert?' WHERE framework='AIACT' AND id='AIACT-A-02.4';
UPDATE public.controls SET req_de='Werden Nutzende zu Schutzbedarf und Schnittstellen in ihrem Zuständigkeitsbereich sensibilisiert? (SOLLTE)' WHERE framework='BSI' AND id='SENS.2.5';
UPDATE public.controls SET req_de='Werden Nutzende von E-Mails zum Erkennen von gefälschten E-Mails sensibilisiert? (SOLLTE)' WHERE framework='BSI' AND id='SENS.7.8';
UPDATE public.controls SET req_de='Werden Nutzende angewiesen, IT-Systeme vor dem Verlassen des Arbeitsplatzes zu sperren? (SOLLTE)' WHERE framework='BSI' AND id='SENS.8.1';
UPDATE public.controls SET req_de='Werden in das zu erstellende Anforderungspaket alle Anforderungen aufgenommen, die für den betrachteten Informationsverbund relevant sind? (MUSS)' WHERE framework='BSI' AND id='STM.2.1';
UPDATE public.controls SET req_de='Wird die Modellierung der Anforderungen aus den Zielobjektkategorien auf die zugeordneten Assets durchgeführt? (MUSS)' WHERE framework='BSI' AND id='STM.5.1';
UPDATE public.controls SET req_de='Wird die Modellierung aller weiteren Anforderungen, denen keine Zielobjektkategorie zugeordnet ist, durchgeführt? (MUSS)' WHERE framework='BSI' AND id='STM.5.4';
