INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0045','Wurden über eine Interessengruppenanalyse die relevanten internen und externen Interessengruppen sowie ihre formalen und impliziten Anforderungen, Erwartungen und Einflussfaktoren ermittelt und im BCMS angemessen berücksichtigt?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0046','Wurden aus der Interessengruppenanalyse die notwendigen Maßnahmen abgeleitet und der Grad der Einflussnahme je Interessengruppe eingeschätzt?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0047','Werden die Interessengruppen sowie deren Anforderungen, Erwartungen und Einflussfaktoren regelmäßig aktualisiert und aktuell gehalten?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0048','Wurde festgelegt, ob, wer, welche Informationen über welches Medium sowie wie häufig und wann mit den Interessengruppen kommuniziert wird?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0049','Ist für regulatorische und sonstige Anforderungen dokumentiert, wo die notwendigen Informationen im Original zu finden sind?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0050','Wurden alle für das BCMS relevanten Schnittstellen ermittelt, klar definiert und dokumentiert, einschließlich der auszutauschenden Informationen bzw. Leistungen, der abgestimmten Methoden sowie Art und Häufigkeit des Austauschs?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0051','Wird in der Business-Impact-Analyse analysiert, welche Geschäftsprozesse zeitkritisch sind, wie lange sie ausfallen dürfen und welche Ressourcen sie im Notbetrieb benötigen?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0052','Wird der Business-Impact-Analyse im Reaktiv- und Aufbau-BCMS ein BIA-Vorfilter vorangestellt?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
