INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0107','Ist technisch sichergestellt, dass die Kommunikations- und Alarmierungstechnik (inkl. Alarmierungssoftware) auch in einem Not- oder Krisenfall zur Verfügung steht und alternative Techniken vorgesehen sind, falls die Technik selbst betroffen ist?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0108','Stehen Kommunikationskanäle zur Verfügung, die unabhängig von der IT der Institution funktionieren?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0109','Sind auch für Ereignisse, die nicht aus einer Störung eskalieren oder als Sicherheitsvorfall eingestuft werden, Kriterien festgelegt, was durch wen an eine Meldestelle gemeldet werden soll?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0110','Sind die relevanten Meldequellen der Institution identifiziert und samt den zuständigen Meldestellen im Notfallhandbuch dokumentiert?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0111','Ist sichergestellt, dass Meldungen die zuständigen Meldestellen erreichen und nicht verloren gehen?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0112','Ist durch Schulungen und Sensibilisierung sichergestellt, dass der Alarmierungs- und Eskalationsprozess allen Mitarbeitenden (und ggf. Externen) bekannt ist und korrekt angewendet wird, und sind die Meldestellen und Kommunikationswege organisationsweit bekannt gegeben?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0113','Erfasst jede Meldestelle die Meldungen in einem einheitlichen Format mit den Mindestinhalten (Zeitpunkt/Ort, meldende Person, betroffene Personen/Bereiche/Prozesse, mögliche Ursache, bereits ergriffene Sofortmaßnahmen, aktuelle Auswirkungen)?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0114','Ist definiert und dokumentiert, wie die Meldestellen während und außerhalb der üblichen Geschäftszeiten erreicht werden können, und ist dies mit den relevanten Stellen (z. B. Institutionsleitung, Personalabteilung, Betriebs-/Personalrat) abgestimmt?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0115','Ist eine nur eingeschränkte Erreichbarkeit einzelner Meldestellen im Notfallhandbuch dokumentiert und wurde dafür eine Risikoübernahme durch die Institutionsleitung herbeigeführt?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0116','Ist bei gesetzlichen/regulatorischen kurzfristigen Meldepflichten sichergestellt, dass diese (z. B. durch Rufbereitschaft oder durchgängige Besetzung) eingehalten werden?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0117','Ist jede Meldestelle anhand klarer, verständlicher und institutions- bzw. meldestellenindividuell festgelegter Kriterien befähigt, initial einzuschätzen, ob ein Ereignis mit Notfallpotenzial vorliegt?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0118','Ist sichergestellt, dass die zuständige Stelle Schadensereignisse mit Notfallpotenzial unverzüglich an eine zentrale Entscheidungsinstanz meldet und dabei bekannte Details, Auswirkungen und bereits eingeleitete Maßnahmen übermittelt?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0119','Ist festgelegt, wie Alarmmeldungen übermittelt werden (z. B. Telefon, Alarm-SMS mit Lesebestätigung, Alarmierungstool)?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0120','Wird die Einstufung, ob eine Störung, ein Notfall oder eine Krise vorliegt, durch eine geschulte, erfahrene und befugte zentrale Entscheidungsinstanz getroffen?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
