INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0129','Regelt der Alarmierungs- und Eskalationsprozess, wie die BAO innerhalb und außerhalb der Geschäftszeiten erreicht wird, welche Personen alarmiert und nachalarmiert werden, welche Kommunikationskanäle genutzt und welche Informationen vermittelt werden?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
