INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0132','Werden weitere Personen, die Alarmmeldungen entgegennehmen könnten (z. B. Haushaltsmitglieder), für den Umgang damit sensibilisiert?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
