INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BCM22301','BCM22301-10.1.1','Bestimmt die Organisation Verbesserungsmöglichkeiten und setzt die notwendigen Maßnahmen um, um die beabsichtigten Ergebnisse ihres BCMS zu erreichen?',NULL,'true','{"quelle": "ISO 22301:2019", "clause": "10.1.1", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, muss='true';
