INSERT INTO public.control_node(node_id,label) VALUES ('KN-00001','Weisen die Verfahren Rollen und Verantwortlichkeiten für die darin enthaltenen Aufgaben zu?'),('KN-00002','Inwieweit werden Informationen während der Übertragung geschützt?'),('KN-00003','Ist ein formaler Change-Prozess mit Genehmigung, Test und Freigabe etabliert?'),('KN-00004','Gibt es getrennte Umgebungen für Entwicklung, Test und Produktion?'),('KN-00005','Sind Zuständigkeiten für die Rollen zugewiesen? (SOLLTE)'),('KN-00006','Ist die Vergabe von Berechtigungen nach dem Prinzip der geringsten Berechtigungen eingeschränkt? (SOLLTE)'),('KN-00007','Inwieweit wird die Eignung von Mitarbeitern für sensible Tätigkeitsbereiche überprüft?'),('KN-00008','Ist für unvereinbare Aufgaben eine Rollentrennung verankert? (SOLLTE)'),('KN-00009','Inwieweit ist Perimeterschutz vorhanden, der den unberechtigten Zutritt verhindert?'),('KN-00010','Werden Zugänge bei Austritt oder Rollenwechsel zeitnah entzogen?'),('KN-00011','Gibt es ein etabliertes Security-Awareness-Programm für alle Mitarbeiter der Organisation?'),('KN-00012','Sind Protokollierungseinrichtungen gegen Manipulation und unbefugten Zugriff geschützt?'),('KN-00013','Werden definierte Schritte unternommen, wenn Nichtkonformitäten identifiziert werden?'),('KN-00014','Hat die Organisation die relevanten Anforderungen dieser interessierten Parteien an das BCMS bestimmt?'),('KN-00015','Sind ausreichende Ressourcen und Budget für Aufbau und Betrieb des BCMS bereitgestellt?'),('KN-00016','Existiert ein Krisenmanagement-Team mit definierten Rollen und Entscheidungsbefugnissen?'),('KN-00017','Werden Übungen ausgewertet, dokumentiert und Verbesserungen abgeleitet?'),('KN-00018','Werden Ergebnisse der Wirksamkeitsprüfungen an die Leitungsebene berichtet?'),('KN-00019','Werden Notfallübungen (inkl. IT-Ausfall-Szenarien) mindestens jährlich durchgeführt?'),('KN-00020','Ist die ausschließliche Verwendung etablierter Algorithmen bei der Schlüsselnutzung verankert? (SOLLTE)'),('KN-00021','Verfügen Informationsverarbeitungseinrichtungen über ausreichende Redundanz, um Verfügbarkeitsanforderungen zu erfüllen?'),('KN-00022','Führt die Organisation für jede Nichtkonformität eine Ursachenanalyse durch?'),('KN-00023','Werden gesetzliche, regulatorische und vertragliche Anforderungen zur Informationssicherheit identifiziert und eingehalten?'),('KN-00024','Sind Maßnahmen zum Umgang mit diesen Risiken/Chancen geplant und in das BCMS integriert?'),('KN-00025','Ist die Kompetenz der BCM-Beteiligten sichergestellt (Nachweise)?'),('KN-00026','Stellt die Organisation sicher, dass ausgelagerte Prozesse und die Lieferkette gesteuert werden?'),('KN-00027','Werden Geschäftsprozesse nach Kritikalität eingestuft und der Ressourcenbedarf für den Notbetrieb ermittelt (BIA)?'),('KN-00028','Sind Kriterien/Schwellen zur Aktivierung der Reaktion (Eskalation) festgelegt?'),('KN-00029','Sind Wiederanlaufpläne (vom Notbetrieb zum Normalbetrieb) je Prozess erstellt?'),('KN-00030','Sind Verfahren und Regelungen zur Messung und Bewertung der Leistung des ISMS verankert? (MUSS)'),('KN-00031','Werden interne Audits des BCMS geplant und durchgeführt?'),('KN-00032','Berücksichtigt die Managementbewertung die Ergebnisse früherer Bewertungen?'),('KN-00033','Werden Trends ermittelt und negative Trends näher untersucht?'),('KN-00034','Werden auf Grundlage der Ergebnisse der Managementbewertung angemessene Maßnahmen ergriffen?'),('KN-00035','Ist die Bewältigungsorganisation (Krisenstab, Notfallteams) mit Rollen etabliert?'),('KN-00036','Sind Geschäftsfortführungspläne (Notbetrieb) je zeitkritischem Prozess erstellt?'),('KN-00037','Wird der physische Zugang auf die Netze eingeschränkt? (KANN)'),('KN-00038','Wird die Software Bill of Materials (SBOM) der Anwendungen dokumentiert? (SOLLTE)'),('KN-00039','Werden vergebene Berechtigungen regelmäßig auf Erforderlichkeit überprüft? (SOLLTE)'),('KN-00040','Sind die Sicherheitsanforderungen an Lieferanten, Dienstleister und Dritte vertraglich geregelt?'),('KN-00041','Werden sicherheitsrelevante Ereignisse aller relevanten IT-Systeme protokolliert?'),('KN-00042','Ist ein Prozess zum Management von Patches/Updates definiert?'),('KN-00043','Wird die Integrität von Installationsdateien getestet? (SOLLTE)'),('KN-00044','Hat die Organisation eine Richtlinie für sichere Anwendungsentwicklung?'),('KN-00045','Wird die Einhaltung der Sicherheitsvorgaben durch den Dienstleister regelmäßig überprüft? (SOLLTE)'),('KN-00046','Inwieweit werden Informationswerte hinsichtlich ihres Schutzbedarfs klassifiziert?'),('KN-00047','Ist eine für die Institution passende Sicherheitsleitlinie festgelegt? (MUSS)'),('KN-00048','Werden ausreichende Ressourcen (Budget, Personal, Werkzeuge) zur Unterstützung des ISMS bereitgestellt?'),('KN-00049','Gibt es physische Zugangskontrollen zu Serverräumen und kritischer Infrastruktur?'),('KN-00050','Werden die Uhren aller Systeme mit genehmigten Zeitquellen synchronisiert?'),('KN-00051','Ist eine geschützte Aufbewahrung von Datensicherungen verankert? (SOLLTE)'),('KN-00052','Werden nach Vorfällen Lessons-Learned durchgeführt und Verbesserungen umgesetzt?'),('KN-00053','Wird die Leitung regelmäßig über Risikolage und Nachweisstand informiert?'),('KN-00054','Werden regelmäßige Security-Awareness-Schulungen für alle Mitarbeiter durchgeführt?'),('KN-00055','Ist ein Verfahren zur Maßregelung verankert? (SOLLTE)'),('KN-00056','Werden rechtlich relevante Beweise rechtssicher dokumentiert? (SOLLTE)'),('KN-00057','Ist ein Verfahren zur kontinuierlichen Verbesserung des ISMS verankert? (MUSS)'),('KN-00058','Ist das Schlüsselmanagement klar definiert und sind die kryptografischen Schlüssel angemessen geschützt?'),('KN-00059','Werden Sicherheitsereignisse zentral gesammelt und korreliert (SIEM oder vergleichbar)?'),('KN-00060','Werden Ihre Wiederherstellungsverfahren in regelmäßigen Abständen systematisch technisch geprüft? (sehr hoch AL3)'),('KN-00061','Wird der Zugriff auf Quellcode und Entwicklungswerkzeuge angemessen gesteuert?'),('KN-00062','Sind Übermittlungen in Drittländer auf zulässige Garantien gestützt (Angemessenheit, SCC, BCR)?'),('KN-00063','Sind Informationswerte inventarisiert, klassifiziert und den Eigentümern zugeordnet?'),('KN-00064','Wird die Einhaltung der Sicherheitsrichtlinien und Standards regelmäßig überprüft?'),('KN-00065','Ist der Meldeweg dokumentiert und dem Personal bekannt?'),('KN-00066','Vernichtet die Organisation Daten in Speichergeräten physisch oder löscht sie sicher vor der Entsorgung?'),('KN-00067','Gibt es einen dokumentierten Prozess für die sichere Konfiguration aller IT-Systeme (Härtung)?'),('KN-00068','Ist Anti-Malware-Schutz auf Endpunkten und Servern aktiv?'),('KN-00069','Sind Maßnahmen nach Stand der Technik für die kritische Anlage umgesetzt (§30/§31 BSIG)?'),('KN-00070','Werden Schwachstellen von Systemkomponenten identifiziert und in ihrer Bedeutung bewertet?'),('KN-00071','Zeigt die oberste Leitung Führung und Verpflichtung zum BCMS?'),('KN-00072','Ist der Ressourcenbedarf im Normal- und Notbetrieb ermittelt?'),('KN-00073','Sind Abhängigkeiten der kritischen Dienstleistung von internen/externen Systemen kartiert?'),('KN-00074','Werden Aktivitäten priorisiert und zeitkritische bestimmt (MTPD)?'),('KN-00075','Sind Wiederherstellungszeitziele (RTO) und Mindestbetriebsniveau (MBCO) festgelegt?'),('KN-00076','Enthält jeder Plan seinen Zweck, Umfang und seine Ziele?'),('KN-00077','Ist die BCM-Dokumentation gelenkt, versioniert und aktuell?'),('KN-00078','Prüfen die internen Audits, ob das BCMS die Anforderungen dieses Dokuments (ISO 22301) erfüllt?'),('KN-00079','Sind Alarmierungswege und Erreichbarkeiten (24/7) festgelegt und getestet?'),('KN-00080','Sind Krisenkommunikation (intern, Kundschaft, Öffentlichkeit, Behörden) und Sprachregelungen vorbereitet?'),('KN-00081','Stehen Kommunikationskanäle zur Verfügung, die unabhängig von der IT der Institution funktionieren?'),('KN-00082','Inwieweit ist die Übermittlung von Daten gemanagt?'),('KN-00083','Werden Vernichtung bzw. Löschung nach Fristablauf durchgeführt und nachweisbar dokumentiert?'),('KN-00084','Erfolgt die Vergabe von Rechten bedarfsorientiert und entsprechend der jeweiligen Rolle oder dem Verantwortungsbereich des Benutzers? (sollte)'),('KN-00085','Werden Standard-Konten und Standard-Passwörter auf allen Geräten und Software geändert?'),('KN-00086','Ist Mehr-Faktor-Authentisierung für weitreichende Berechtigungen aktiviert? (SOLLTE)'),('KN-00087','Ist im Vertrag mit den KI-Anbietern ein Recht auf eigene Audits ausdrücklich verankert?'),('KN-00088','Wird die Funktionsfähigkeit der automatisierten Angriffserkennung überwacht? (SOLLTE)'),('KN-00089','Werden erkannte Schwachstellen nach Risikobewertung priorisiert und zeitnah behoben?'),('KN-00090','Werden Informationen über Bedrohungen systematisch gesammelt und analysiert (Threat Intelligence)?'),('KN-00091','Ist die Architektur nach dem Prinzip "Security by Design" verankert? (SOLLTE)'),('KN-00092','Sind messbare ISMS-Ziele festgelegt, dokumentiert und in der gesamten Organisation kommuniziert?'),('KN-00093','Ist der ISB der Unternehmensführung direkt unterstellt? (MUSS)'),('KN-00094','Werden Informationssicherheitsanforderungen von Beginn an und über den gesamten Verlauf in Projekten systematisch berücksichtigt?'),('KN-00095','Werden Umgebungsbedingungen (Temperatur, Luftfeuchtigkeit) in Geräte-Hosting-Bereichen überwacht?'),('KN-00096','Ist die Ausführung nicht autorisierter Anwendungen eingeschränkt? (SOLLTE)'),('KN-00097','Wird für Daten eine Offline-Kopie regelmäßig ausgeführt? (SOLLTE)'),('KN-00098','Wird die Einhaltung von Verpflichtungen regelmäßig sowie anlassbezogen überprüft? (SOLLTE)'),('KN-00099','Überprüft die oberste Leitung die ISMS-Wirksamkeit in geplanten Intervallen?'),('KN-00100','Werden Nutzende zur Rückgabe nicht mehr benötigter Assets angewiesen? (SOLLTE)'),('KN-00101','Sind die Testfälle abdeckende, aber unkritische Testdaten verankert? (SOLLTE)'),('KN-00102','Werden Sicherheitstests (SAST, DAST, Code Review) im Entwicklungsprozess durchgeführt?'),('KN-00103','Ist die Verarbeitung auf das notwendige Maß beschränkt (Datenminimierung)?'),('KN-00104','Ist der BSI-Meldeprozess für erhebliche Störungen etabliert (unverzüglich)?'),('KN-00105','Inwieweit ist der Umgang mit mobilen IT-Geräten und mobilen Datenträgern geregelt?'),('KN-00106','Gibt es eine Richtlinie für sicheres Arbeiten im Homeoffice/Remote Work?'),('KN-00107','Sind Aufbewahrungsfristen für Protokolldaten definiert und technisch durchgesetzt?'),('KN-00108','Reagiert die Organisation auf Vorfälle über ein definiertes Incident-Response-Programm?'),('KN-00109','Ist eine Netzwerksegmentierung auf Basis der Ergebnisse der Risikoanalyse umgesetzt, sodass schützenswerte Bereiche voneinander getrennt sind? [muss]'),('KN-00110','Ist der Zutritt zu RZ, Backup-Lager und sensiblen Bereichen beschränkt und protokolliert?'),('KN-00111','Sind prozessual die Vergabe und der Entzug von Zugangsberechtigungen festgelegt (Art. 21 e RTS RMF)? (MUSS)'),('KN-00112','Gibt es einen Prozess zur Verwaltung der Kapazitätsanforderungen für alle Systeme basierend auf der Kritikalität der Geschäftsprozesse?'),('KN-00113','Inwieweit wird die Sicherung und Wiederherstellung von Daten und IT-Diensten sichergestellt?'),('KN-00114','Ist risikoorientiert ein Datensicherungskonzept festgelegt (Art. 12 Abs. 2 DORA)? (MUSS)'),('KN-00115','Ist prozessual geregelt, dass im Rahmen der Planung von wesentlichen Änderungen eine Risikobewertung durchgeführt wird (Art. 8 Abs. 3 DORA)? (MUSS)'),('KN-00116','Inwieweit wird die Nutzung kryptografischer Verfahren verwaltet?'),('KN-00117','Bewertet und steuert die Organisation Risiken aus Beziehungen zu Lieferanten und Geschäftspartnern?'),('KN-00118','Ist die Nutzung personenbezogener Daten auf festgelegte Zwecke begrenzt?'),('KN-00119','Werden Einwilligungen nachweisbar, freiwillig und widerrufbar eingeholt?'),('KN-00120','Ist ein Prozess zur Meldung von Datenpannen an Betroffene und Behörden etabliert?'),('KN-00121','Wird MFA für alle Fernzugriffe und VPN-Sitzungen erzwungen?'),('KN-00122','Existiert ein aktuelles Verzeichnis aller IT-Dienstleister und Lieferanten mit Kritikalitätsbewertung?'),('KN-00123','Inwieweit werden Benutzerkonten und Anmeldeinformationen sicher verwaltet?'),('KN-00124','Werden relevante Sicherheits-/Datenschutzanforderungen an externe Parteien kommuniziert?'),('KN-00125','Werden Verantwortlichkeiten für Informationssicherheit bei Beendigung oder Wechsel des Arbeitsverhältnisses geregelt?'),('KN-00126','Sind alle Mitarbeiter und Projektbeteiligten persönlich zur Geheimhaltung verpflichtet? [muss]'),('KN-00127','Sind unterstützende Versorgungseinrichtungen (Strom, Klima, Wasser) gegen Ausfälle geschützt?'),('KN-00128','Werden Sicherheitsanforderungen bei der Beschaffung neuer IT-Systeme als Auswahlkriterium berücksichtigt?'),('KN-00129','Werden regelmäßig Penetrationstests durch qualifizierte Dritte durchgeführt?'),('KN-00130','Werden interne Audits des ISMS regelmäßig durchgeführt?'),('KN-00131','Ist für kritische KI-Systeme eine Wiederanlaufzeit (Recovery Time Objective, RTO) verbindlich definiert?'),('KN-00132','Werden personenbezogene Daten (PII) bei der Übertragung und bei der Speicherung durch Verschlüsselung oder Pseudonymisierung geschützt?'),('KN-00133','Sind Risiken und potenzielle Schäden (auch für Dritte/Gesellschaft) identifiziert?'),('KN-00134','Werden Risikoakzeptanzen formell von der Leitungsebene genehmigt und dokumentiert?'),('KN-00135','Ist die Architektur der Anwendungen dokumentiert? (SOLLTE)'),('KN-00136','Ist eine Aufbewahrungsfrist für die Protokolldaten von mindestens sechs Monaten festgelegt und umgesetzt?'),('KN-00137','Werden Sicherheit und Resilienz (inkl. adversarial) des KI-Systems geprüft?'),('KN-00138','Sind KI-spezifische Vorfallstypen ausdrücklich im Incident-Response-Plan berücksichtigt?'),('KN-00139','Bewahrt die Organisation dokumentierte Information als Nachweis über die Ergebnisse aller Korrekturmaßnahmen auf?'),('KN-00140','Wird das BCMS fortlaufend hinsichtlich Eignung, Angemessenheit und Wirksamkeit verbessert?'),('KN-00141','Sind interessierte Parteien und ihre BC-Erfordernisse identifiziert?'),('KN-00142','Ist der Anwendungsbereich des BCMS (inkl. Ausschlüsse begründet) festgelegt?'),('KN-00143','Leitet und unterstützt die oberste Leitung Personen, damit sie zur Wirksamkeit des BCMS beitragen?'),('KN-00144','Ist die BC-Politik kommuniziert und interessierten Parteien verfügbar?'),('KN-00145','Werden Risiken und Chancen für das BCMS bestimmt?'),('KN-00146','Sind die Personen sich der BC-Politik und ihres Beitrags bewusst?'),('KN-00147','Sind die tätigen Personen sich der Folgen bewusst, die eine Nichterfüllung der Anforderungen des BCMS nach sich zieht?'),('KN-00148','Ist geregelt, worüber, wann, mit wem und wie im BC-Kontext kommuniziert wird?'),('KN-00149','Sind Namenskonventionen und Dokumentenlenkungsprozesse (Titel, Datum, Autor, Version, Genehmigung) definiert und werden befolgt?'),('KN-00150','Sind dokumentierte Informationen vor Verlust von Vertraulichkeit, Integrität und Verfügbarkeit geschützt und ordnungsgemäß für Aufbewahrung und Lesbarkeit gespeichert?'),('KN-00151','Sind Schadenskategorien und -kriterien für die BIA definiert?'),('KN-00152','Wählt der oder die BCB je Ressourcenkategorie eine oder mehrere geeignete BC-Strategien vor?'),('KN-00153','Dokumentiert und pflegt die Organisation die Business-Continuity-Pläne und -Verfahren?'),('KN-00154','Sind Rollen der Notfallmanagement-Organisation definiert und besetzt?'),('KN-00155','Sind Warnung und Kommunikation (intern/extern, Behörden, Medien) im Vorfall geregelt?'),('KN-00156','Ist jeder Plan zu der Zeit und an dem Ort, an dem er benötigt wird, nutzbar und verfügbar?'),('KN-00157','Sind risikoorientiert Rahmenbedingungen für die Durchführung von Tests festgelegt? (MUSS)'),('KN-00158','Führt die Organisation Übungen und Tests durch, die mit ihren Business-Continuity-Zielen im Einklang stehen?'),('KN-00159','Werden regelmäßig Krisenübungen und -simulationen unter Beteiligung aller relevanten Personen und Entscheidungsträger durchgeführt? [sehr hoch (AL3)]'),('KN-00160','Bewertet die Organisation die Eignung, Angemessenheit und Wirksamkeit ihrer Business-Impact-Analyse, Risikobewertung, Strategien, Lösungen, Pläne und Verfahren?'),('KN-00161','Werden die Informationssicherheitsleistung und die ISMS-Wirksamkeit systematisch bewertet?'),('KN-00162','Plant, erstellt, implementiert und pflegt die Organisation ein internes Auditprogramm?'),('KN-00163','Führt die oberste Leitung Managementbewertungen des BCMS durch (Input/Output dokumentiert)?'),('KN-00164','Berücksichtigt die Managementbewertung Änderungen bei externen und internen Themen, die für das BCMS relevant sind?'),('KN-00165','Berücksichtigt die Managementbewertung Rückmeldungen von interessierten Parteien?'),('KN-00166','Enthalten die Bewertungsergebnisse Entscheidungen zur kontinuierlichen Verbesserung und notwendigen ISMS-Änderungen?'),('KN-00167','Werden die identifizierten Risiken systematisch bewertet und wird für jedes Risiko eine dokumentierte Entscheidung über seine Behandlung (z. B. vermeiden, vermindern, übertragen od'),('KN-00168','Sind Ausweichmöglichkeiten (Standorte, mobile Arbeit, Cloud) vorbereitet?'),('KN-00169','Wird der Leitung regelmäßig über Status und Risikolage im BCM berichtet?'),('KN-00170','Ist ein BCMS nach BSI-Standard 200-4 bzw. einem anerkannten BCM-Standard verankert? (KANN)'),('KN-00171','Ist die Alarmierung der BAO verankert? (SOLLTE)'),('KN-00172','Gibt es eine Exit-Strategie für den Wechsel kritischer Cloud- oder IT-Dienstleister?'),('KN-00173','Werden Verbindungen zwischen OT-Systemen und anderen IT-Systemen eingeschränkt? (SOLLTE)'),('KN-00174','Sind Verfahren und Regelungen zum Management von Informationen und damit verbundener Assets verankert? (MUSS)'),('KN-00175','Ist ein Inventar der Informationen und damit verbundener Assets dokumentiert? (SOLLTE)'),('KN-00176','Gibt es ein gepflegtes Software-Inventar aller eingesetzten Anwendungen und deren Versionen?'),('KN-00177','Sind Regeln für die akzeptable Nutzung von Informationen und Assets definiert und kommuniziert?'),('KN-00178','Wurde eine Vorgehensweise zur Außerbetriebnahme, Aussonderung und Löschung von Datenträgern definiert? (MUSS)'),('KN-00179','Sind Verfahren und Regelungen zum Identitäts- und Berechtigungsmanagement verankert? (MUSS)'),('KN-00180','Wird eine eindeutige Identität zu genau einer natürlichen Person oder einem IT-System zugewiesen? (SOLLTE)'),('KN-00181','Wird die zugeordnete Identität bei Weggang von Nutzenden deaktiviert? (SOLLTE)'),('KN-00182','Gibt es ein definiertes Limit für fehlgeschlagene Anmeldeversuche, mit einem Verfahren zur Meldung von Sicherheitsproblemen?'),('KN-00183','Werden gemeinsam genutzte Benutzer-IDs/Konten nur bei geschäftlicher Notwendigkeit mit entsprechenden Genehmigungen autorisiert?'),('KN-00184','Ist für Anwendungen von externen Netzanschlüssen Phishing-resistente Mehr-Faktor-Authentisierung aktiviert? (SOLLTE)'),('KN-00185','Sind Rollen und Verantwortlichkeiten im Zusammenhang mit der Nutzung und Verwaltung von Cloud-Diensten definiert?'),('KN-00186','Werden für Cloud-Dienste Rechtsraum und Datenlokation dokumentiert? (SOLLTE)'),('KN-00187','Wird für Einkäufe ein Zertifikat oder Testat nach einem passenden Sicherheitsstandard vereinbart? (KANN)'),('KN-00188','Sind Kündigungs- und Exit-Regelungen einschließlich Datenrückgabe und nachweisbarer Löschung vertraglich vereinbart?'),('KN-00189','Werden für Dienstleistungen die organisatorischen Schnittstellen des Dienstleisters dokumentiert? (SOLLTE)'),('KN-00190','Gibt es einen definierten Prozess für die sichere Beendigung von Dienstleisterverhältnissen?'),('KN-00191','Sind Kommunikationskontaktdaten und Meldemedien für Sicherheitsereignisse allen Mitarbeitern klar bereitgestellt?'),('KN-00192','Werden Zertifikate zentral verwaltet und rechtzeitig erneuert?'),('KN-00193','Ist ein Umgang mit Schwachstellen festgelegt? (MUSS)'),('KN-00194','Werden technische Schwachstellen aktiv erkannt, bewertet und zeitnah behoben (Schwachstellenmanagement)?'),('KN-00195','Werden bei sicherheitskritischen Ereignissen die betroffenen Nutzenden informiert? (SOLLTE)'),('KN-00196','Ist die Bereitstellung von Sicherheitsupdates mindestens für einen bestimmten Zeitraum verankert? (SOLLTE)'),('KN-00197','Ist der nachvollziehbar abgegrenzte Geltungsbereich nach Freigabe der Institutionsleitung festgelegt? (MUSS)'),('KN-00198','Ist die festgelegte Sicherheitsleitlinie durch die Institutionsleitung autorisiert? (MUSS)'),('KN-00199','Sind die erforderlichen Kompetenzen für Personen, die an ISMS-bezogenen Aktivitäten arbeiten, klar definiert?'),('KN-00200','Inwieweit werden die zu sichernden Räumlichkeiten auf Einbruch überwacht?') ON CONFLICT (node_id) DO NOTHING;
INSERT INTO public.control_node(node_id,label) VALUES ('KN-00201','Ist sichergestellt, dass API-Schlüssel ausschließlich in einem Secrets Manager verwaltet und nicht fest im Code hinterlegt werden?'),('KN-00202','Wird bei Anwendungen die Änderung von Default-Zugangsdaten ausgeführt? (SOLLTE)'),('KN-00203','Sind bei IT-Systemen nicht benötigte Systemfunktionen deaktiviert? (SOLLTE)'),('KN-00204','Ist sichergestellt, dass unautorisierte Änderungen an Konfiguration oder Befehlen verhindert oder zuverlässig erkannt werden?'),('KN-00205','Werden sensible Daten im Ruhezustand (at rest) verschlüsselt?'),('KN-00206','Ist bei Endgeräten die Verwaltung durch ein Mobile Device Management (MDM) aktiviert? (SOLLTE)'),('KN-00207','Ist die Isolierung von bestimmten Anwendungen aktiviert? (KANN)'),('KN-00208','Ist der Schutz des Arbeitsspeichers vor der Ausnutzung bekannter Sicherheitslücken aktiviert? (SOLLTE)'),('KN-00209','Ist bei Anwendungen die automatische Installation von Sicherheitsupdates aktiviert? (SOLLTE)'),('KN-00210','Sind alternative Sicherheitsmechanismen, die in Notfällen greifen, verankert? (SOLLTE)'),('KN-00211','Ist die Vorgehensweise zur Wiederherstellung dokumentiert? (SOLLTE)'),('KN-00212','Werden im Rahmen des Monitorings und der Auswertung Sicherheitsvorfälle laufend überwacht, sodass sicherheitsrelevante Ereignisse erkannt werden? (MUSS)'),('KN-00213','Gibt es spezifische Schulungen für Mitarbeiter mit erhöhten IT-Rechten (Administratoren)?'),('KN-00214','Sind Verfahren und Regelungen zur Behandlung von Sicherheitsvorfällen verankert? (MUSS)'),('KN-00215','Wird die Abwehrfähigkeit durch Übungen regelmäßig überprüft? (KANN)'),('KN-00216','Werden bisherige Maßnahmen anhand von Erkenntnissen aus Informationssicherheitsvorfällen regelmäßig überprüft? (SOLLTE)'),('KN-00217','Sind einheitliche Methoden nach einem anerkannten Standard verankert? (MUSS)'),('KN-00218','Werden Nutzende zum Melden von sicherheitsrelevanten Ereignissen angewiesen? (SOLLTE)'),('KN-00219','Sind die eingesetzten KI-Systeme in die IT-Grundschutz-Modellierung aufgenommen worden?'),('KN-00220','Wird vor wesentlichen Änderungen die Einhaltung der Sicherheitsanforderungen getestet? (SOLLTE)'),('KN-00221','Werden kritische Änderungen auch durch eine von der Implementierung unabhängige Person autorisiert? (KANN)'),('KN-00222','Ist nach einem fehlerhaften Update ein Rollback oder eine Wiederherstellung in einen funktionsfähigen Zustand möglich?'),('KN-00223','Wird die Wirksamkeit der umgesetzten Maßnahmen regelmäßig überprüft? (MUSS)'),('KN-00224','Wurde ein Protokollierungskonzept für KI-Systeme gemäß BSI-Baustein OPS.1.1.5 erstellt?'),('KN-00225','Werden nicht benötigte Dienste und Ports auf allen Systemen deaktiviert?'),('KN-00226','Ist die Datenübertragbarkeit (Portabilität) in gängigem Format sichergestellt?'),('KN-00227','Sind die Fristen und der Ablauf des Offenlegungsprozesses für gemeldete Schwachstellen klar definiert und festgelegt?'),('KN-00228','Werden eingehende Schwachstellenmeldungen nachverfolgt und erhalten die Meldenden eine Rückmeldung zur Bearbeitung?'),('KN-00229','Wählt und entwickelt die Organisation Kontrollaktivitäten zur Risikominderung auf akzeptable Niveaus?'),('KN-00230','Ist die Meldepflicht gegenüber dem BSI in den Reaktionsprozess integriert, sodass meldepflichtige Vorfälle fristgerecht an das BSI gemeldet werden?'),('KN-00231','Gibt es eine Richtlinie für die sichere Nutzung privater Geräte (BYOD)?'),('KN-00232','Wird die Informationssicherheits-Leitlinie von der Unternehmensführung beschlossen und innerhalb des Unternehmens kommuniziert (Art. 5 Abs. 2b DORA)? (MUSS)'),('KN-00233','Werden die Abhängigkeiten der Informationswerte untereinander erhoben und dokumentiert, inklusive der logischen Kette von Prozess über Anwendung und IT-System bis zur IT-Infrastruk'),('KN-00234','Werden Audit-Tests und Prüfungen so geplant, dass operative Systeme nicht beeinträchtigt werden?'),('KN-00235','Gibt es eine Passwort-Richtlinie, die Mindestlänge, Komplexität und Änderungsintervalle definiert?'),('KN-00236','Werden risikoorientiert Authentifizierungsmethoden für den physischen Zutritt festgelegt (Art. 21 f RTS RMF)? (MUSS)'),('KN-00237','Wird der vollständige Lebenszyklus von Identitäten verwaltet (Erstellung, Änderung, Deaktivierung)?'),('KN-00238','Werden Sicherheitsereignisse bewertet und ggf. als Vorfall eingestuft?'),('KN-00239','Prüfen Sie Ihre Kontinuitätsplanung regelmäßig einschließlich vollständiger Wiederherstellung, Rückversetzung in einen bekannten Zustand und Einhaltung festgelegter Zeitvorgaben? ('),('KN-00240','Werden durch das ISM die vertraglich zu berücksichtigenden Anforderungen zur Informationssicherheit an den Dienstleister definiert und wird deren Einhaltung überwacht?'),('KN-00241','Werden Daten nur so lange gespeichert wie nötig (Speicherbegrenzung, Löschkonzept)?'),('KN-00242','Liegt für jede Verarbeitung eine gültige Rechtsgrundlage vor?'),('KN-00243','Informiert die Organisation betroffene Personen über ihre Datenschutzpraktiken?'),('KN-00244','Ist ein Prozess für Auskunftsersuchen der Betroffenen umgesetzt?'),('KN-00245','Ist ein Prozess zur Berichtigung unrichtiger Daten etabliert?'),('KN-00246','Sind Schutzmaßnahmen bei automatisierten Einzelentscheidungen/Profiling getroffen (menschliches Eingreifen)?'),('KN-00247','Sind mit Auftragsverarbeitern Verträge (AVV) mit den Pflichtinhalten geschlossen?'),('KN-00248','Wird ein Verzeichnis von Verarbeitungstätigkeiten (VVT) geführt und aktuell gehalten?'),('KN-00249','Werden Sicherheitsziele, -pflichten und -richtlinien intern kommuniziert?'),('KN-00250','Unterliegen Sicherheitsrichtlinien regelmäßigen Überprüfungen in definierten Intervallen?'),('KN-00251','Zeigt das Management aktive Unterstützung für die Sicherheitsrichtlinie und stellt sicher, dass das Personal ein angemessenes Sicherheitsbewusstsein erreicht?'),('KN-00252','Sind Regeln für physischen und logischen Zugriff auf Informationen und Assets etabliert?'),('KN-00253','Enthalten Verträge mit IT-Dienstleistern verbindliche Sicherheitsanforderungen und Audit-Rechte?'),('KN-00254','Werden Sicherheitsanforderungen auch an Unterauftragnehmer (Sub-Dienstleister) weitergegeben?'),('KN-00255','Gibt es eine dokumentierte Richtlinie für die sichere Nutzung von Cloud-Diensten?'),('KN-00256','Testet die Organisation die Wiederanlaufverfahren zur Systemwiederherstellung?'),('KN-00257','Entwickelt, implementiert und kommuniziert die Geschäftsleitung eine Richtlinie zum Schutz personenbezogener Daten? (MUSS)'),('KN-00258','Inwieweit wird das ISMS von einer unabhängigen Stelle überprüft?'),('KN-00259','Setzen Richtlinien und dokumentierte Betriebsverfahren die Kontrollen operativ um?'),('KN-00260','Sind Berechtigungskonzepte für den Zugriff auf Informationen erstellt und dokumentiert? (sollte)'),('KN-00261','Sind Verfahren zur Vergabe und zum Entzug von Zutrittsberechtigungen etabliert? [sollte]'),('KN-00262','Werden IT-Anlagen vor physischen und umweltbedingten Bedrohungen geschützt (Feuer, Wasser, Strom)?'),('KN-00263','Ist die Verkabelung (Strom und Netzwerk) vor Abhören und Beschädigung geschützt?'),('KN-00264','Werden IT-Geräte regelmäßig gewartet, um Verfügbarkeit und Integrität sicherzustellen?'),('KN-00265','Gibt es Verfahren für die sichere Entsorgung oder Wiederverwendung von IT-Geräten?'),('KN-00266','Sind Auswertungsregeln/Use-Cases und Alarmschwellen für Protokolldaten definiert und werden sie gepflegt?'),('KN-00267','Werden geeignete Ereignisprotokolle geführt und regelmäßig überprüft?'),('KN-00268','Ist das Netzwerk segmentiert und wird der Zugriff auf die Segmente überwacht?'),('KN-00269','Werden Secure-Coding-Richtlinien angewendet (z.B. OWASP Top 10)?'),('KN-00270','Fordert die Geschäftsleitung aktiv die Einhaltung der Sicherheitsrichtlinien von allen Mitarbeitern?'),('KN-00271','Ist die Richtlinie ordnungsgemäß dokumentiert, den Mitarbeitern kommuniziert und relevanten interessierten Parteien zugänglich gemacht?'),('KN